export const LEVELS = [['basics', 'Basics'], ['maths', 'Mathematics'], ['advanced', 'Advanced']];
export const getLecture = id => LECTURES.find(l => l.id === id);
export const findNote = file => { for (const l of LECTURES) { const n = l.notes.find(x => x.file === file); if (n) return { lecture: l.id, note: n.id }; } return null; };
